import{z as i,x as A,o as r,c as p,q as o,j as l,D as t,d as e,s as B,S as s,b as E}from"./chunks/framework.C8m1ZpeB.js";const X=JSON.parse('{"title":"波带片光学","description":"","frontmatter":{"title":"波带片光学","date":"2026-09-27T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/zone-plate-optics.md","filePath":"litho/zone-plate-optics.md","lastUpdated":1791063341000}'),d={name:"litho/zone-plate-optics.md"};function D(m,a,f,h,_,u){const n=A("Mermaid");return r(),p("div",null,[a[2]||(a[2]=o('<h1 id="波带片光学" tabindex="-1">波带片光学 <a class="header-anchor" href="#波带片光学" aria-label="Permalink to &quot;波带片光学&quot;">​</a></h1><div class="epigraph"><p>没有透镜能折射 X 射线，就给波前画同心圆环：亮环透、暗环挡，一块「波带片」让 X 射线学会聚焦。</p><footer>—— 据 Fresnel zone plate 光学；X-ray 显微/光刻应用文献（Attwood《Soft X-Rays and Extreme Ultraviolet Radiation》）</footer></div><p><a href="/litho/euv-dose-budget">EUV 剂量预算</a>管的是反射式光学的预算，本课回到更短的波长：X 射线几乎不折射也不易反射，常规透镜全数失效。缺口是<strong>波带片（zone plate）</strong>——用衍射而非折射聚焦的「伪透镜」。它是 X 射线光刻、光束线聚焦与最近的 X 射线显微镜的共同起点。本课不做全息光学的一般理论。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>波长越短分辨率越高，但光学元件的路线图在 X 射线段断链：折射率接近 1（透镜失去屈光力）、反射率除掠入射外趋零。缺口：<strong>给 X 射线造一个聚焦元件</strong>。Fresnel 的答案：不用「弯折光线」，用「相长干涉的几何」——只保留波前上相位相干贡献的环带。</p><p><span class="marginnote">术语翻译：波带片（Fresnel zone plate）= 一组半径递减的同心透明/不透明环，环半径满足 \\(r_n\\approx\\sqrt{n\\lambda f}\\)——相邻透光带的相位差 \\(2\\pi\\)，在焦点相长叠加；数值孔径 NA ≈ λ/(2Δr)，最外环宽 Δr 决定分辨率。</span></p><p><span class="marginnote">数字实例：λ=1nm、焦距 f=1cm 的波带片，最外环宽 Δr=25nm 时 NA≈0.02、理论分辨率 ≈ λ/(2NA)≈25nm——分辨率由最外环的<strong>制造精度</strong>决定，环要刻到几十纳米且同心，本身就要用电子束光刻来做——「用光刻造光学的镜」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>设计三步：定波长与焦距 → 算环半径序列 \\(r_n=\\sqrt{n\\lambda f+(n\\lambda/2)^2}\\) → 交给电子束光刻 + 电镀（金/镍）做成振幅或相位型。相位型（环厚设计成 π 相位差）比振幅型衍射效率高约 4 倍——这是现代 X 射线显微镜的标准配置。光刻场景的用法：接触式 X 射线光刻时代波带片做聚束，同步辐射光束线用大口径波带片把光聚到微米点。</p>',9)),(r(),l(s,null,{default:t(()=>[B(n,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%AE%9A%20%CE%BB%20%E4%B8%8E%20f%22%5D%20--%3E%20B%5B%22%E7%AE%97%E7%8E%AF%E5%8D%8A%E5%BE%84%20r_n%3D%E2%88%9A(n%CE%BBf)%22%5D%0A%20%20B%20--%3E%20C%5B%22%E7%94%B5%E5%AD%90%E6%9D%9F%E5%85%89%E5%88%BB%E7%8E%AF%E5%B8%A6%22%5D%0A%20%20C%20--%3E%20D%5B%22%E7%94%B5%E9%95%80%E7%9B%B8%E4%BD%8D%2F%E6%8C%AF%E5%B9%85%E5%9E%8B%22%5D%0A%20%20D%20--%3E%20E%7B%22%E8%A1%8D%E5%B0%84%E6%95%88%E7%8E%87%22%7D%0A%20%20E%20--%3E%7C%22%E6%8C%AF%E5%B9%85%E5%9E%8B%20~10%25%22%7C%20F%5B%22%E4%BA%AE%E4%BD%86%E8%B4%B9%E5%85%89%22%5D%0A%20%20E%20--%3E%7C%22%E7%9B%B8%E4%BD%8D%E5%9E%8B%20~40%25%22%7C%20G%5B%22X%20%E5%B0%84%E7%BA%BF%E6%98%BE%E5%BE%AE%E9%95%9C%E6%A0%87%E9%85%8D%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,[E("span",{class:"marginnote"},"直觉类比：像「合唱队只留同拍的人」——舞台（波前）上每位歌手（子波）到听众的路程不同、相位杂乱；波带片把路程差恰为整数波长的歌手留下（透光环带）、其余请出去（挡环带），留下的歌声在听众席（焦点）同相叠加，声音反而最响。")],-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,[e("衍射机制：环带把波前切成「相位对齐的圆环集合」，各环对焦点的光程差为整数波长——菲涅尔半波带理论的正用。分辨率的机制冷酷：NA = λ/(2Δr)，Δr 是制造精度，所以"),E("strong",null,"波带片的分辨率直接撞在光刻工艺上"),e("——最外环 25nm 就需要 25nm 级电子束光刻，这既是它的上限也是它与现代半导体工艺的缘分（制造它正是半导体业的拿手活）。色差机制是软肋：\\(r_n\\propto\\sqrt{\\lambda}\\)，波长一变焦点就移，X 射线的单色性（同步辐射 Δλ/λ ~ 10⁻⁴）因此是前提。")],-1)),(r(),l(s,null,{default:t(()=>[B(n,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%7B%22%E4%B8%BA%E4%BD%95%E8%83%BD%E8%81%9A%E7%84%A6%3F%22%7D%20--%3E%20R%5B%22%E7%8E%AF%E5%B8%A6%E4%BF%9D%E7%9B%B8%E4%BD%8D%E5%AF%B9%E9%BD%90%E5%AD%90%E6%B3%A2%22%5D%0A%20%20R%20--%3E%20S%5B%22%E7%84%A6%E7%82%B9%E7%9B%B8%E9%95%BF%E5%B9%B2%E6%B6%89%22%5D%0A%20%20T%7B%22%E5%88%86%E8%BE%A8%E7%8E%87%E4%B8%8A%E9%99%90%3F%22%7D%20--%3E%20U%5B%22NA%3D%CE%BB%2F2%CE%94r%22%5D%0A%20%20U%20--%3E%20V%5B%22%CE%94r%3D%E5%88%B6%E9%80%A0%E7%B2%BE%E5%BA%A6%20%E2%86%92%20%E6%92%9E%E5%85%89%E5%88%BB%22%5D%0A%20%20W%7B%22%E8%89%B2%E5%B7%AE%E4%B8%BA%E4%BD%95%E8%87%B4%E5%91%BD%3F%22%7D%20--%3E%20X%5B%22r_n%E2%88%9D%E2%88%9A%CE%BB%22%5D%0A%20%20X%20--%3E%20Y%5B%22%E5%8D%95%E8%89%B2%E6%80%A7%E6%98%AF%E5%89%8D%E6%8F%90%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=o('<p><span class="marginnote">常见误区：把波带片当「透镜的替代品」从能量效率看——它吃掉大部分光（振幅型只透 ~10%），同步辐射的亮度预算因此更紧；另一误区是「环越多越好」——环数决定聚焦深度与效率，但最外环精度不变时分辨率不变，环多只增益光通量。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>波带片的适用半径：微米级焦斑的 X 射线显微（生物、电池原位成像）、光束线聚焦、以及实验性的 X 射线光刻；大面积平行曝光用不了它（口径与效率都不够），这也是 X 射线光刻败给 EUV 反射式路线的原因之一。制造边界：厚高比（环要够厚才挡得住硬 X 射线，但环宽纳米级）是电镀工艺的极限拉扯；多层劳厄透镜（MLL）用多层膜堆叠逼近更硬的 X 射线，是波带片的「重装版」。与<a href="/litho/offner-relay">Offner 中继成像</a>的呼应：两者都是「常规透镜失效处的替代光学」——一个用衍射对付 X 射线，一个用反射环形镜对付紫外像差。</p><p><span class="marginnote">直觉类比：波带片之于 X 射线，像「用节拍器组织人群」——没有喇叭（透镜），就让人群（波前）按节拍分组前进，同拍的一起喊（相长干涉），杂音互相抵消；组织得越细（外环越窄），声音聚得越尖（分辨率越高）。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>波带片 = 相位对齐的同心环，衍射聚焦补上 X 射线无透镜的空白。</li><li>分辨率 = λ/2Δr，直接撞电子束光刻的制造精度。</li><li>相位型效率 ~40%；色差要求单色光；大面积光刻非其所长。</li><li>出处：Attwood《Soft X-Rays and EUV Radiation》；Fresnel 半波带理论；XRM 显微镜应用综述。</li></ul>',6))])}const F=i(d,[["render",D]]);export{X as __pageData,F as default};
